@Controller('movies')
export class MovieController {
  constructor(private readonly movies: MovieService) {}
  @Get(':id')
  async show(@Param('id') id: string, @Res() res: Response) {
    const movie = await this.movies.find(id);              // one model
    if (res.req.accepts(['html', 'json']) === 'html') {
      return res.render('movie', { movie });               // template engine view
    }
    return res.json(plainToInstance(MovieDto, movie));     // serialized representation
  }
}
